<?php namespace App\Services; use App\Contracts\UsdtWalletOwnershipVerifier; final class MultiNetworkUsdtWalletOwnershipVerifier implements UsdtWalletOwnershipVerifier { public function __construct(private Bep20WalletOwnershipVerifier $bep20,private TronWalletOwnershipVerifier $tron){} public function verify(string $network,string $address,string $message,string $signature):bool { return match($network) { "BEP20"=>$this->bep20->verify($network,$address,$message,$signature),"TRC20"=>$this->tron->verify($network,$address,$message,$signature),default=>false }; } }